import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        long base = 0;
        long[] gain = new long[n];
        for (int i = 0; i < n; i++) {
            base += Math.min(a[i], b[i]);
            gain[i] = Math.min(a[i], 2 * b[i]) - Math.min(a[i], b[i]);
        }
        Arrays.sort(gain);
        for (int i = 0; i < k; i++) base += Math.max(0, gain[n - 1 - i]);  // largest gains first
        System.out.println(base);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a, b := make([]int64, n), make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range b {
		b[i] = nextInt()
	}
	var base int64
	gain := make([]int64, n)
	for i := 0; i < n; i++ {
		base += min(a[i], b[i])
		gain[i] = min(a[i], 2*b[i]) - min(a[i], b[i])
	}
	slices.Sort(gain)
	for i := 0; i < k; i++ {
		base += max(0, gain[n-1-i]) // largest gains first
	}
	fmt.Println(base)
}
